Proceso SumaDePares
    Definir Mutable cantidad Como Entero <- 0;
    Definir Mutable valor Como Entero <- 0;
    Leer cantidad;
    Definir Mutable suma Como Entero <- 0;
    Para i <- 1 Hasta cantidad Con Paso 1 Hacer
        Leer valor;
        Si valor mod 2 = 0 Entonces
            suma <- suma + valor;
        FinSi
    FinPara
    Escribir suma;
FinProceso
